.dwo-root{position:absolute;inset:0;overflow:hidden;background:var(--wa-bg, #05050a);z-index:5;font-family:"Pretendard Variable","Pretendard","Malgun Gothic",-apple-system,system-ui,sans-serif;font-size:16px;font-weight:400;font-style:normal;line-height:normal;letter-spacing:normal;color:var(--wa-text, #fff);text-align:left;text-transform:none;word-spacing:normal;-webkit-font-smoothing:antialiased}
.dwo-root,.dwo-root *,.dwo-root *::before,.dwo-root *::after{box-sizing:border-box}
.dwo-root *{margin:0;padding:0;border:0 solid transparent;background:none;font:inherit;color:inherit;text-decoration:none}
.dwo-root img{display:block;border:0;max-width:none}
.dwo-root > [data-node-id]{will-change:transform}
.dwo-root [hidden]{display:none!important}
.dwo-root [data-sh-theme="dark"]{display:none!important}
.dwo-root[data-theme="dark"] [data-sh-theme="dark"]{display:block!important}
.dwo-root[data-theme="dark"] [data-sh-theme="dark"]{display:none!important}
.dwo-root .n1_9308{background-color:color-mix(in srgb, var(--wa-point, rgb(57 103 253)) 5%, transparent);align-content:stretch;display:flex;gap:8px;align-items:center;justify-content:center;padding-left:18px;padding-right:18px;padding-top:8px;padding-bottom:8px;position:relative;border-radius:6px;flex-shrink:0}
.dwo-root .n1_9308::after{content:"";position:absolute;inset:-0px;border:1px solid var(--wa-point, #b5c6fa);border-radius:6px;pointer-events:none}
.dwo-root .n1_9309{word-break:break-word;font-family:"Pretendard Variable","Pretendard","Malgun Gothic",-apple-system,system-ui,sans-serif;font-weight:400;line-height:16px;font-style:normal;position:relative;flex-shrink:0;color:var(--wa-point, #3967fd);font-size:13px;white-space:nowrap;width:45px}
.dwo-root .n1_3460{display:flex;align-items:center;justify-content:center;position:relative;flex-shrink:0}
.dwo-root .x24{position:absolute;display:block;inset:0;max-width:none;width:100%;height:100%}
.dwo-root[data-theme="dark"]{color:var(--wa-point, #e3e9f2)}
.dwo-root[data-theme="dark"] [data-name="Header"] > [data-name="Background"]{background:var(--wa-bg, #131519)!important;box-shadow:inset 0 -1px 0 rgba(255,255,255,.06)!important}
.dwo-root[data-theme="dark"] [data-name="Input"],.dwo-root[data-theme="dark"] [data-name="Select"],.dwo-root[data-theme="dark"] [data-name^="Field/ID"],.dwo-root[data-theme="dark"] [data-name^="Field/Password"]{background-color:var(--wa-bg, #111316)}
.dwo-root[data-theme="dark"] [data-name="Widget/Notice"] > div:first-child,.dwo-root[data-theme="dark"] [data-name="Widget/Help Desk"] > div:first-child,.dwo-root[data-theme="dark"] [data-name="Panel"] > div:first-child{background-image:linear-gradient(180deg,color-mix(in srgb, var(--wa-surface, rgb(33 36 43)) 64%, transparent),color-mix(in srgb, var(--wa-bg, rgb(19 21 26)) 76%, transparent))!important;background-color:transparent!important;backdrop-filter:blur(18px) saturate(1.15)!important;-webkit-backdrop-filter:blur(18px) saturate(1.15)!important}
.dwo-root[data-theme="dark"] [data-name="Widget/Notice"] > div:nth-child(3),.dwo-root[data-theme="dark"] [data-name="Widget/Help Desk"] > div:nth-child(3),.dwo-root[data-theme="dark"] [data-name="Panel"] > div:nth-child(3){box-shadow:inset 0 1px 0 rgba(255,255,255,.1),inset 0 0 0 1px rgba(255,255,255,.07),0 24px 48px rgba(0,0,0,.34)!important}
.dwo-root[data-theme="dark"] > [data-node-id]:has([data-name^="Widget/"]) > [data-name="Header"] > [data-name="Background"]{background:color-mix(in srgb, var(--wa-bg, rgb(14 16 20)) 68%, transparent)!important;backdrop-filter:blur(18px)!important;-webkit-backdrop-filter:blur(18px)!important}
.dwo-root[data-theme="dark"] [data-name^="Step/"] > div:first-child{background-color:color-mix(in srgb, var(--wa-point, rgb(130 155 255)) 12%, transparent)}
.dwo-root[data-theme="dark"] [data-name^="Widget/"] [data-name="List Item/Post"]{background-color:color-mix(in srgb, var(--wa-bg, rgb(255 255 255)) 4.5%, transparent)}
.dwo-root[data-theme="dark"] [data-name="Count"]{background-color:color-mix(in srgb, var(--wa-bg, rgb(255 255 255)) 10%, transparent)!important}
.dwo-root[data-theme="dark"] [data-name="Login Card"] > div:first-child{background-image:linear-gradient(180deg,color-mix(in srgb, var(--wa-surface, rgb(33 36 43)) 62%, transparent),color-mix(in srgb, var(--wa-bg, rgb(19 21 26)) 74%, transparent))!important;background-color:transparent!important;backdrop-filter:blur(18px)!important;-webkit-backdrop-filter:blur(18px)!important}
.dwo-root[data-theme="dark"] [data-name="Login Card"] > div:nth-child(2){box-shadow:inset 0 1px 0 rgba(255,255,255,.12),inset 0 0 0 1px rgba(255,255,255,.08),0 30px 60px rgba(0,0,0,.4)!important}
.dwo-root[data-theme="dark"] [data-name="Search Overlay"] > [data-name="Background"],.dwo-root[data-theme="dark"] [data-name="Background"][data-node-id="1:6533"]{background-color:var(--wa-surface, #17191e)!important}
.dwo-root[data-theme="dark"] .n1_9309{color:var(--wa-point, #8ba6ff)}
